settings.custom_css:
/* DUABARIS */
selector .elementskit-navbar-nav{justify-content:space-between;width:100%;}
selector .elementskit-menu-container{width:100%;}
/* DUABARIS2 */
selector .elementskit-navbar-nav .ekit-menu-nav-link{font-size:15px;padding-left:10px;padding-right:10px;}
/* DUABARIS3 */
selector .elementskit-navbar-nav{gap:4px;align-items:stretch;}
selector .elementskit-navbar-nav .ekit-menu-nav-link{font-size:15px;line-height:20px;padding:14px 18px !important;border-radius:6px;transition:background .2s,color .2s,box-shadow .2s;}
selector .elementskit-navbar-nav .ekit-menu-nav-link:hover,selector .elementskit-navbar-nav li:hover .ekit-menu-nav-link{background:#F5F5F5;color:#073C64 !important;box-shadow:inset 0 -3px 0 #C8E86D;}
selector .elementskit-navbar-nav .ekit-menu-nav-link.active{box-shadow:inset 0 -3px 0 #C8E86D;}
/* DUABARIS6 */
selector .elementskit-navbar-nav{justify-content:flex-start !important;gap:10px !important;align-items:center !important;}
selector .elementskit-navbar-nav .ekit-menu-nav-link{display:flex !important;align-items:center;height:48px !important;box-sizing:border-box;margin:0 !important;padding:0 18px !important;}
selector .elementskit-navbar-nav li{height:auto !important;}
/* DUABARIS8 */
selector.elementor-element .elementskit-navbar-nav li a.ekit-menu-nav-link.ekit-menu-nav-link:hover,selector.elementor-element .elementskit-navbar-nav li:hover a.ekit-menu-nav-link.ekit-menu-nav-link,selector.elementor-element .elementskit-navbar-nav li a.ekit-menu-nav-link.active{background:transparent !important;box-shadow:none !important;border:0 !important;border-radius:0 !important;color:#003D79 !important;}
selector .elementskit-navbar-nav .ekit-menu-nav-link::before,selector .elementskit-navbar-nav .ekit-menu-nav-link::after{display:none !important;}
/*DUABARIS9*/
selector .elementskit-navbar-nav .elementskit-dropdown{top:calc(100% - 12px)!important;}
selector .elementskit-navbar-nav li.menu-item-has-children a{position:relative;}
selector .elementskit-navbar-nav li.menu-item-has-children a::after{content:"";position:absolute;left:0;right:0;top:100%;height:16px;}
/*PONTON*/
selector .elementskit-navbar-nav .elementskit-dropdown::before{content:"";position:absolute;left:0;right:0;top:-24px;height:24px;}

/*PENDIDIKAN2*/
@media(min-width:1025px){
selector .elementskit-navbar-nav li.menu-item-864>.elementskit-dropdown{column-count:2;}
selector .elementskit-navbar-nav li.menu-item-864>.elementskit-dropdown>li:nth-child(4){break-before:column;}
}
